INSERT INTO "workspace_reservations" VALUES('00000000-0000-0000-0000-00000000001f','ws-24e3faab9931f7d8fb4358ab3af1ac01','d973c9c103d1d393e4b96fdd7c75045ac248a54f8ae8cc05240fedcc640b9091','97256692d7888f3de438e8d2f672b49e2a5567a9bb871f6f7e40bf0e55833f97','<fixture-root>/workspaces/cancelled','read','00000000-0000-0000-0000-00000000001e','parent','00000000-0000-0000-0000-00000000001e','099a888f9f35c97739d0ebeb16b29bbb2a948ec71cd3e4b89f2e3af0c3a01407','released','2026-01-01T00:00:00.000Z','2026-01-01T00:00:00.000Z','2026-01-01T00:00:00.000Z');
CREATE INDEX tasks_state_idx ON tasks(state, created_at);
CREATE INDEX tasks_request_idx ON tasks(request_id);
CREATE INDEX attempts_task_idx ON attempts(task_id, generation);
CREATE UNIQUE INDEX attempts_effective_unique ON attempts(task_id)
    WHERE execution_state IN ('starting','executing','finalizing','uncertain');
CREATE INDEX attempts_active_idx ON attempts(execution_state);
CREATE INDEX attempts_model_family_idx
    ON attempts(model_adapter, model_provider, model_model) WHERE model_model IS NOT NULL;
CREATE INDEX workers_state_idx ON workers(state);
CREATE INDEX messages_task_idx ON messages(task_id, created_at);
CREATE INDEX messages_state_idx ON messages(state);
CREATE INDEX artifacts_task_idx ON artifacts(task_id);
CREATE INDEX events_task_idx ON events(task_id, seq);
CREATE INDEX events_decision_status_idx ON events(kind, seq DESC)
    WHERE kind IN ('decision.completed','decision.failed','decision.needs_host','decision.cancelled','decision.stale');
CREATE INDEX commands_kind_idx ON commands(kind, created_at);
CREATE INDEX resource_claims_state_idx ON resource_claims(state, kind);
CREATE INDEX attempt_activity_task_idx ON attempt_activity(task_id, updated_at);
CREATE INDEX evaluation_profiles_current_idx ON evaluation_profiles(available, profile_id);
CREATE INDEX evaluation_profiles_adapter_idx ON evaluation_profiles(adapter, profile_id);
CREATE INDEX evaluation_preferences_mode_idx ON evaluation_preferences(mode, profile_id);
CREATE INDEX evaluation_evidence_profile_idx
    ON evaluation_evidence(profile_id, created_at);
CREATE INDEX evaluation_readers_open_idx ON evaluation_readers(released_at, expires_at);
CREATE INDEX evaluation_writers_queue_idx ON evaluation_writers(state, generation);
CREATE INDEX evaluation_evidence_pending_profile_idx
    ON evaluation_evidence_pending(profile_id, created_at);
CREATE INDEX evaluation_evidence_pending_created_idx
    ON evaluation_evidence_pending(created_at, evidence_id);
CREATE INDEX evaluation_evidence_created_idx
    ON evaluation_evidence(created_at, evidence_id);
CREATE INDEX evaluation_evidence_run_idx ON evaluation_evidence(run_id);
CREATE INDEX evaluation_evidence_counted_idx ON evaluation_evidence(profile_id, counted);
CREATE INDEX evaluation_samples_profile_idx ON evaluation_samples(profile_id, created_at);
CREATE INDEX evaluation_card_history_profile_idx
    ON evaluation_card_history(profile_id, table_revision);
CREATE INDEX decision_requests_created_idx ON decision_requests(created_at, decision_id);
CREATE INDEX decision_requests_task_idx ON decision_requests(task_id);
CREATE INDEX evaluation_decisions_created_idx
    ON evaluation_decisions(created_at, decision_id);
CREATE INDEX events_review_seq_idx
    ON events(seq) WHERE kind IN ('task.accepted','task.rejected','workflow.acknowledged');
CREATE VIEW effective_preferences AS
SELECT p.profile_id AS profile_id,
       COALESCE(o.mode, f.mode) AS mode,
       CASE WHEN o.profile_id IS NOT NULL THEN o.reason ELSE f.reason END AS reason,
       CASE WHEN o.profile_id IS NOT NULL THEN 'override' ELSE 'family' END AS source
FROM evaluation_profiles p
LEFT JOIN evaluation_preferences o ON o.profile_id = p.profile_id
LEFT JOIN family_preferences f ON f.adapter = p.adapter AND f.provider = p.provider AND f.model = p.model
WHERE (o.profile_id IS NOT NULL AND o.mode != 'none') OR (o.profile_id IS NULL AND f.mode IS NOT NULL);
CREATE INDEX objectives_activity_idx ON objectives(activity_seq DESC, objective_id DESC);
CREATE INDEX objectives_project_idx ON objectives(project_id, activity_seq DESC, objective_id DESC);
CREATE INDEX workflow_runs_state_idx ON workflow_runs(state, updated_at);
CREATE INDEX workflow_runs_objective_idx ON workflow_runs(objective_id, activity_seq DESC, run_id DESC);
CREATE INDEX workflow_runs_activity_idx ON workflow_runs(activity_seq);
CREATE INDEX workflow_routes_run_idx ON workflow_routes(run_id);
CREATE INDEX workflow_turns_run_idx ON workflow_turns(run_id, turn_index);
CREATE INDEX workflow_turns_attempt_idx ON workflow_turns(attempt_id);
CREATE INDEX workflow_requests_run_idx ON workflow_requests(run_id, state);
CREATE INDEX workflow_children_parent_idx ON workflow_children(parent_run_id, state);
CREATE INDEX workflow_continuations_run_idx ON workflow_continuations(run_id, state);
CREATE UNIQUE INDEX workflow_continuations_auto_unique
    ON workflow_continuations(run_id, request_id) WHERE authorized_by='auto';
CREATE UNIQUE INDEX workspace_reservations_writer_unique
    ON workspace_reservations(checkout_id) WHERE state='held' AND access='write';
CREATE INDEX workspace_reservations_checkout_idx ON workspace_reservations(checkout_id, state);
CREATE INDEX workspace_reservations_holder_idx ON workspace_reservations(holder_task_id, state);
